package ci_test

// tiers_golden_test.go — golden-file test for the tier table.
//
// The golden file is testdata/ci-tiers.golden.md. It is regenerated by
// `task ci:render-tiers`, which writes both the golden file and the
// published document (docs/reference/ci-tiers.md).
//
// The test is separated from tiers_contract_test.go because it has a
// different failure mode: a golden-file mismatch means the model
// changed and the golden file was not regenerated; a contract
// mismatch means the model and the artifact disagree. The two
// failures have different remedies (regenerate the golden file vs.
// fix the artifact).

import (
	"os"
	"path/filepath"
	"testing"
)

// TestTierGolden_HasNoCRLF asserts the golden file uses LF line
// endings. A CRLF golden file would fail on a Windows contributor's
// machine and produce a spurious diff.
func TestTierGolden_HasNoCRLF(t *testing.T) {
	root := repoRoot(t)
	path := filepath.Join(root, "internal", "ci", "testdata", "ci-tiers.golden.md")
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v", path, err)
	}
	if filepath.Ext(path) == ".md" && containsCRLF(data) {
		t.Fatalf("%s contains CRLF line endings; use LF", path)
	}
}

// containsCRLF reports whether data contains a CRLF sequence.
func containsCRLF(data []byte) bool {
	for i := 0; i < len(data)-1; i++ {
		if data[i] == '\r' && data[i+1] == '\n' {
			return true
		}
	}
	return false
}
